html`&lt;p class="dash-note"&gt;Each cell counts ${measureLabel} for one failed part and one hazard, using all your other filters. &lt;strong&gt;Click a cell&lt;/strong&gt; to filter the whole dashboard to it, and click it again to clear.&lt;/p&gt;`







{
  const counts = new Map();
  for (const d of heatRows) {
    const k = d.failed_component + "|" + d.hazard_group;
    counts.set(k, (counts.get(k) ?? 0) + w(d));
  }
  const maxV = d3.max(counts.values()) || 1;
  const color = d3.scaleSequential([0, maxV], d3.interpolateBlues);
  const table = html`&lt;table class="heat"&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;${hazards.map(h =&gt; html`&lt;th scope="col"&gt;${h}&lt;/th&gt;`)}&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;&lt;/tbody&gt;
  &lt;/table&gt;`;
  const tbody = table.querySelector("tbody");
  for (const c of components) {
    const tr = html`&lt;tr&gt;&lt;th scope="row"&gt;${c}&lt;/th&gt;&lt;/tr&gt;`;
    for (const h of hazards) {
      const v = counts.get(c + "|" + h) ?? 0;
      const selected = component === c && hazard === h;
      const td = html`&lt;td tabindex="0"&gt;${v ? fmtN(Math.round(v)) : ""}&lt;/td&gt;`;
      td.style.background = v ? color(Math.max(v, maxV * 0.12)) : "#ffffff";
      td.style.color = v &gt; maxV * 0.5 ? "#ffffff" : "#1f2a33";
      td.title = `${c}, ${h}: ${fmtN(Math.round(v))} ${measureLabel}`;
      if (selected) td.classList.add("selected");
      const pick = () =&gt; {
        setInput(viewof component, selected ? "All" : c);
        setInput(viewof hazard, selected ? "All" : h);
      };
      td.onclick = pick;
      td.onkeydown = e =&gt; { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(); } };
      tr.append(td);
    }
    tbody.append(tr);
  }
  const wrap = html`&lt;div class="heat-wrap"&gt;&lt;/div&gt;`;
  wrap.append(table);
  return wrap;
}

